  ", además se lleva un sello, como mucho uno al día. Para eso comprobamos que está en tu local con la ubicación de su móvil (no la guardamos).": ", le client reçoit aussi un tampon, un par jour maximum. Pour ça, on vérifie qu’il est dans ton établissement grâce à la position de son téléphone (on ne l’enregistre pas).",
  ", como mucho uno al día por persona y tarjeta.": ", un par jour maximum par personne et par carte.",
  ", quien escanee el cartel del local en tu negocio se lleva además un sello, con el mismo tope de uno al día.": ", celui qui scanne l’affiche dans ton établissement reçoit en plus un tampon, avec la même limite d’un par jour.",
  ", redondo y pequeño en Descubre, el mapa y los resultados. Las fotos del local, en tu ficha.": ", petit et rond dans Découvrir, sur la carte et dans les résultats. Les photos de l’établissement, sur ta fiche.",
