  "Al día, con pago por transferencia. Sin permanencia y sin comisión por canje.": "À jour, payé par virement. Sans engagement et sans commission sur les échanges.",
  "Al día. Sin permanencia y sin comisión por canje.": "À jour. Sans engagement et sans commission sur les échanges.",
  "Al eliminarlo anulamos las reservas y los códigos sin usar y avisamos a cada persona; también a quien tiene sellos, un premio o un regalo, y a tu equipo. Solo guardamos los datos de facturación el tiempo que obliga la ley.": "En le supprimant, nous annulons les réservations et les codes non utilisés et prévenons chaque personne, ainsi que ceux qui ont des tampons, une récompense ou un cadeau, et ton équipe. Nous ne gardons les données de facturation que le temps exigé par la loi.",
