  "Como mucho, cupones al mes por persona": "Coupons par mois et par personne, maximum",
  "Como no tienes local fijo, cada publicación lleva su sitio.": "Comme tu n’as pas de lieu fixe, chaque publication indique son lieu.",
  "Como un cartel: el título enorme y la fecha arriba. Ideal para eventos.": "Comme une affiche : le titre en énorme et la date en haut. Idéal pour les événements.",
  "Compartir": "Partager",
