  "Comprobado: sale lo mismo.": "Vérifié : le résultat est le même.",
  "Comprobamos que representas a la entidad antes de hacerla pública (normalmente en 24–48 h); hasta entonces no se puede publicar. Hace falta tener 18 años. De momento, las entidades no pagan cuota.": "On vérifie que tu représentes l’organisation avant de la rendre publique (en général sous 24 à 48 h) ; d’ici là, impossible de publier. Il faut avoir 18 ans. Pour l’instant, les organisations ne paient pas d’abonnement.",
  "Comprobando la entidad": "Vérification de l’organisation",
  "Comprobando…": "Vérification…",
  "Comprobar el resultado": "Vérifier le résultat",
  "Comprueba que el horario está bien. Si lo está, confírmalo.": "Vérifie que tes horaires sont corrects. Si c’est le cas, confirme-les.",
  "con carné": "avec carte",
  "Con carné de estudiante": "Avec carte étudiante",
  "Con carné joven": "Avec carte jeune",
  "con condiciones": "avec conditions",
  "Con el": "Avec le",
  "Con el aforo en directo, lo que marques manda 30 minutos.": "Avec la jauge en direct, ce que tu indiques à la main l’emporte pendant 30 minutes.",
  "Con el negocio bloqueado o en pausa puedes descontar usos de los bonos que ya tiene la gente, pero no cargar bonos nuevos.": "Tant que l’établissement est bloqué ou en pause, tu peux décompter les utilisations des carnets que les gens ont déjà, mais pas en charger de nouveaux.",
  "Con el negocio parado solo puedes dar lo que ya tenía la gente: sellos y usos de bonos.": "Avec ton établissement à l’arrêt, tu ne peux offrir que ce que les gens avaient déjà : tampons et utilisations de carnets.",
  "Con el negocio parado solo puedes dar usos de bonos que la gente ya tiene: los sellos nuevos y «algo del momento» vuelven cuando se reactive.": "Avec ton établissement à l’arrêt, tu ne peux offrir que des utilisations de carnets que les gens ont déjà : les nouveaux tampons et « un petit plus du moment » reviennent dès qu’il est réactivé.",
  "Con el plan anual, escríbenos y alargamos la renovación.": "Avec la formule annuelle, écris-nous et nous repousserons le renouvellement.",
  "Con el precio, la línea y la comida/cena de arriba. No se publica los días cerrados ni si ese día ya has publicado uno. Te avisamos para que añadas la foto.": "Avec le prix, la ligne et le déjeuner/dîner ci-dessus. Il n’est pas publié les jours de fermeture ni si tu en as déjà publié un ce jour-là. On te prévient pour que tu ajoutes la photo.",
  "Con enlace a «{offer_title}»": "Avec un lien vers « {offer_title} »",
  "Con fecha y hora. Puede tener precio y enlace para entradas.": "Avec une date et une heure. Peut avoir un prix et un lien vers la billetterie.",
  "Con fecha, aforo y reserva de plaza": "Avec date, capacité et réservation de places",
  "Con la cámara o escribiendo el código": "Avec la caméra ou en saisissant le code",
  "Con la misma cuenta que usas en la app o en la web. Si tu negocio todavía no está dado de alta, entra y lo das de alta aquí mismo.": "Avec le même compte que dans l’app ou sur le site. Si ton établissement n’est pas encore inscrit, connecte-toi et inscris-le ici même.",
  "con reserva": "avec réservation",
