  "Con todo hasta el {fin}. El {due_on} se suma a tu suscripción, sin cortes.": "Tout compris jusqu’au {fin}. Le {due_on}, il rejoint ton abonnement, sans interruption.",
  "Con «Dar en el momento» das sellos, un uso de un bono o algo del momento sin que el cliente enseñe nada: él escanea tu QR.": "Avec « Offrir sur le moment », tu offres des tampons, une utilisation d’un carnet ou un petit extra sans que le client montre quoi que ce soit : c’est lui qui scanne ton QR.",
