  "Crea la primera: «al décimo café, uno gratis». Puedes tener hasta {max}, cada una con lo suyo.": "Crée la première : « au dixième café, un offert ». Tu peux en avoir jusqu’à {max}, chacune avec ses propres règles.",
  "Crea una gratis": "Crées-en un gratuitement",
  "Crea uno, por ejemplo «10 cafés por 12 €» o «5 clases por 40 €». Lo cobras tú en el local y Klendar lleva la cuenta de los usos.": "Crées-en un, par exemple « 10 cafés pour 12 € » ou « 5 cours pour 40 € ». Tu l’encaisses toi-même sur place et Klendar tient le compte des utilisations.",
  "Crea uno: la gente participa gratis y, si quieres, añade tu negocio a favoritos.": "Crées-en un : les gens participent gratuitement et, s’ils le veulent, ajoutent ton commerce à leurs favoris.",
