  "Croquetas de jamón": "Croquettes au jambon",
  "Crustáceos": "Crustacés",
  "Cualquiera": "Peu importe",
  "Cualquiera de tu equipo marca desde Mi negocio, con un toque, cómo está el local: Hay sitio, Casi lleno o Lleno. Sale en tu ficha y en el mapa mientras estás abierto, y se quita solo a las 2 horas. Con el aforo en directo, se pone solo.": "N’importe qui de ton équipe indique depuis Mon commerce, en un clic, l’affluence : Il y a de la place, Presque plein ou Complet. Ça s’affiche sur ta fiche et sur la carte tant que tu es ouvert, et ça s’efface tout seul au bout de 2 heures. Avec l’affluence en direct, ça se met tout seul.",
  "Cuando alguien te pida presupuesto para un grupo, lo verás aquí.": "Quand quelqu’un te demandera un devis pour un groupe, tu le verras ici.",
  "Cuando el local está abierto": "Quand l’établissement est ouvert",
  "Cuando hayas corregido lo que te dijimos, pídenos que lo miremos otra vez. Si quieres, cuéntanos qué has cambiado. Normalmente contestamos en 24–48 h.": "Quand tu auras corrigé ce qu’on t’a indiqué, demande-nous de regarder à nouveau. Si tu veux, dis-nous ce que tu as changé. On répond en général sous 24 à 48 h.",
  "Cuando participes en uno, lo verás aquí con tu número.": "Quand tu participeras à un tirage au sort, tu le verras ici avec ton numéro.",
  "Cuando quien lleva el negocio cree un bono, lo verás aquí para venderlo.": "Quand le responsable de l’établissement créera un carnet, tu le verras ici pour le vendre.",
  "Cuando quien lleva el negocio cree un sorteo, lo verás aquí.": "Quand la personne qui gère le commerce créera un tirage au sort, tu le verras ici.",
  "Cuando se acaban las plazas, la gente puede apuntarse. Si se libera una, avisamos por orden y cada persona tiene un rato para cogerla (30 minutos en una oferta flash, 2 horas en un evento).": "Quand il n’y a plus de places, les gens peuvent s’inscrire. Si une place se libère, on prévient dans l’ordre et chaque personne a un moment pour la prendre (30 minutes pour une offre flash, 2 heures pour un événement).",
  "Cuando tienen una fecha nueva cerca": "Quand ils ont une nouvelle date près de chez toi",
  "Cuando un bar cercano diga qué partidos pone, saldrán aquí.": "Quand un bar proche indiquera les matchs qu’il diffuse, ils s’afficheront ici.",
  "Cuando un negocio cerca organice uno, saldrá aquí.": "Quand un établissement proche en organisera un, il apparaîtra ici.",
  "Cuando valides códigos, aquí verás lo que te traen tus ofertas.": "Quand tu valideras des codes, tu verras ici ce que tes offres te rapportent.",
  "Cuando vendas un bono, lo verás aquí con quién lo vendió y cada uso.": "Quand tu vendras un carnet, tu le verras ici avec qui l’a vendu et chaque utilisation.",
  "Cuatro por folio, para recortar. Se imprimen o se guardan en PDF desde el navegador.": "Quatre par feuille, à découper. On les imprime ou on les enregistre en PDF depuis le navigateur.",
