  "Cuéntanos sobre tu negocio: lo revisamos antes de hacerlo público (normalmente en 24-48 h). Mientras, ya puedes preparar publicaciones.": "Parle-nous de ton commerce : on le vérifie avant de le rendre public (en général sous 24 à 48 h). En attendant, tu peux déjà préparer tes publications.",
  "Cóbralo en el local antes de cargarlo: Klendar no cobra nada. Si te equivocas, lo puedes deshacer durante 10 minutos.": "Encaisse-le sur place avant de l’ajouter : Klendar ne prend rien. En cas d’erreur, tu peux annuler pendant 10 minutes.",
