  "Degustación gratis": "Dégustation gratuite",
  "Deja de pagarse con la suscripción desde hoy (Stripe ajusta la próxima factura). El local no se borra; su plan vuelve a como estaba antes de pagar.": "Il n’est plus payé par l’abonnement à partir d’aujourd’hui (Stripe ajuste la prochaine facture). Le lieu n’est pas supprimé ; sa formule redevient celle d’avant le paiement.",
  "Deja de salir para vender. Los que ya vendiste siguen valiendo hasta que se gasten o caduquen.": "Il ne sera plus proposé à la vente. Ceux que tu as déjà vendus restent valables jusqu’à ce qu’ils soient épuisés ou expirés.",
  "Deja de verse en la app y en la web. Los premios ya entregados se quedan en el historial.": "Elle n’apparaîtra plus dans l’app ni sur le web. Les récompenses déjà remises restent dans l’historique.",
  "Dejar de seguir": "Ne plus suivre",
  "Dejar el sorteo": "Quitter le tirage au sort",
  "Dejaremos de revisarla y el documento se borrará. Podrás volver a pedirla cuando quieras.": "Nous arrêterons de l’examiner et le document sera supprimé. Tu pourras refaire la demande quand tu veux.",
  "Dejará de funcionar para siempre (también su QR). Lo que trajo se queda en sus cifras.": "Il ne fonctionnera plus jamais (son QR code non plus). Ce qu’il a apporté reste dans ses chiffres.",
  "Dejará de poder validar códigos y de ver el panel.": "La personne ne pourra plus valider de codes ni voir le tableau de bord.",
  "Dejará de publicarse sola. Lo que ya se publicó se queda como está.": "Elle ne se publiera plus toute seule. Ce qui a déjà été publié reste tel quel.",
  "Dejarás de ver este panel y de validar sus códigos. Avisaremos al propietario.": "Tu ne verras plus ce tableau de bord et ne pourras plus valider ses codes. Nous préviendrons le propriétaire.",
  "Dejarás de ver su panel y de validar sus códigos. Avisaremos al propietario. Para volver, tendrán que invitarte otra vez.": "Tu ne verras plus son tableau de bord et ne pourras plus valider ses codes. Nous préviendrons le propriétaire. Pour revenir, il faudra qu’on t’invite à nouveau.",
