  "El aforo en directo está apagado": "La jauge en direct est désactivée",
  "El aforo en directo está apagado.": "La jauge en direct est désactivée.",
  "El aforo lo pones y lo cuentas tú, y tiene que ser real. Klendar no controla el aforo legal de tu local.": "La capacité, c’est toi qui la fixes et qui comptes, et elle doit être réelle. Klendar ne contrôle pas la capacité légale de ton établissement.",
  "El aforo no cierra las reservas del evento.": "La jauge ne ferme pas les réservations de l’événement.",
  "El avisador de pedidos está apagado": "Les alertes de commande sont désactivées",
  "El banco ha devuelto el recibo del plan.": "La banque a rejeté le prélèvement de la formule.",
  "El banco ha devuelto el recibo. Escríbenos a info@klendar.app para ponerlo al día.": "La banque a rejeté le prélèvement. Écris-nous à info@klendar.app pour régulariser.",
  "El bono lo vendes y lo cumples tú: Klendar solo lleva la cuenta de los usos y no cobra nada. Tienes que respetar los bonos vendidos aunque los pauses o los quites.": "C’est toi qui vends le carnet et qui l’honores : Klendar tient seulement le compte des utilisations et ne prend rien. Tu dois honorer les carnets vendus, même si tu les mets en pause ou que tu les retires.",
  "El bono se paga en el local, como siempre: Klendar no cobra nada y solo lleva la cuenta de los usos.": "Le carnet se paie sur place, comme d’habitude : Klendar ne prend rien et tient seulement le compte des utilisations.",
  "El bono vuelve a estar a la venta": "Le carnet est de nouveau en vente",
  "El botón dirá: {etiqueta}": "Le bouton affichera : {etiqueta}",
  "El cambio vale desde ya: Stripe descuenta lo que no has usado del plan de ahora y cobra la diferencia.": "Le changement s'applique tout de suite : Stripe déduit ce que tu n'as pas utilisé de la formule actuelle et facture la différence.",
  "El cambio vale desde ya: Stripe descuenta lo que no has usado del plan de ahora y cobra la diferencia. Precios sin IVA.": "Le changement s’applique tout de suite : Stripe déduit ce que tu n’as pas utilisé de la formule actuelle et facture la différence. Prix hors TVA.",
  "el carné de estudiante": "ta carte étudiante",
  "el carné joven": "ta carte jeune",
  "El cartel que tengas impreso dejará de funcionar.": "L’affiche que tu as imprimée ne marchera plus.",
  "El cartel que tienes impreso dejará de valer al momento y tendrás que imprimir el nuevo. Hazlo si alguien lo usa sin venir (por ejemplo, con una foto del cartel).": "L’affiche que tu as imprimée ne marchera plus immédiatement et tu devras imprimer la nouvelle. Fais-le si quelqu’un l’utilise sans venir (par exemple, avec une photo de l’affiche).",
  "El cliente escanea el QR con la app o con la cámara del móvil y lo acepta. Una vez por persona; como mucho 5 al día en tu negocio.": "Le client scanne le QR avec l’appli ou l’appareil photo de son téléphone et l’accepte. Une fois par personne ; 5 par jour au maximum dans ton établissement.",
  "el cliente te paga a ti, como siempre": "le client te paie directement, comme d’habitude",
  "El cobro es tuyo, en la puerta: aquí solo contamos plazas a precio de tarifa.": "C’est toi qui encaisses, à l’entrée : ici, on compte juste les places au prix affiché.",
  "El contacto se borra de Klendar 30 días después de la fecha.": "Le contact est supprimé de Klendar 30 jours après la date.",
  "El Corte Inglés": "El Corte Inglés",
  "El código guarda la plaza": "Le code réserve la place",
  "El código ha caducado: pide que generen otro.": "Le code a expiré : demande au client d’en générer un autre.",
  "el código no caduca": "le code n’expire pas",
  "El código no guarda sitio: cuentan los que entran. Para conciertos o fiestas, donde siempre falla alguien. Cuando se llena, los que lleguen después ya no pasan.": "Le code ne réserve pas de place : seules les entrées comptent. Pour les concerts ou les soirées, où il y a toujours des absents. Une fois complet, les retardataires ne peuvent plus entrer.",
  "El código puede valer de 1 a 24 horas.": "Le code peut être valable de 1 à 24 heures.",
