  "El descuento tiene que ser del 5 al 50 %.": "La réduction doit être comprise entre 5 et 50 %.",
  "El descuento «Otro» cabe en 24 caracteres («2ª unidad −50 %»).": "La réduction « Autre » tient en 24 caractères (« 2e article −50 % »).",
  "el DNI (mayores de 65)": "ta pièce d’identité (plus de 65 ans)",
  "El día de su cumpleaños, quien tiene tu negocio en favoritos recibe una notificación y un código de regalo que validas como cualquier otro.": "Le jour de leur anniversaire, ceux qui ont ton commerce en favori reçoivent une notification et un code cadeau que tu valides comme n’importe quel autre.",
  "El día del evento, usa «Asistentes» para dar entrada.": "Le jour de l’événement, utilise « Participants » pour faire entrer les gens.",
  "El enlace tiene que empezar por https:// y ser una dirección web válida.": "Le lien doit commencer par https:// et être une adresse web valide.",
  "El enlace vuelve a funcionar": "Le lien fonctionne à nouveau",
  "El fin debe ser posterior al inicio.": "La fin doit être après le début.",
  "El fin tiene que ser posterior al principio.": "La fin doit être après le début.",
  "El gratis de lanzamiento está a punto de acabar.": "La période gratuite de lancement se termine bientôt.",
  "El mapa no se puede cargar ahora mismo. Escribe la dirección y pulsa «Buscar en el mapa»: la localizamos igual.": "La carte ne peut pas se charger pour le moment. Saisis l’adresse et appuie sur « Chercher sur la carte » : on la localisera quand même.",
  "El mensaje tiene que tener entre 5 y 240 caracteres.": "Le message doit faire entre 5 et 240 caractères.",
