  "El más bajo de los últimos 30 días.": "Le plus bas des 30 derniers jours.",
  "El negocio sigue igual hasta el final de lo pagado; después no se renueva. Te mandamos un correo de confirmación.": "Ton commerce continue comme avant jusqu’à la fin de la période payée ; ensuite, l’abonnement n’est pas renouvelé. On t’envoie un e-mail de confirmation.",
  "el nombre debe tener entre 2 y 60 caracteres": "le nom doit faire entre 2 et 60 caractères",
  "El nombre del enlace cabe en 40 caracteres.": "Le nom du lien tient en 40 caractères.",
  "El nombre puede tener 40 caracteres como mucho.": "Le nom peut faire 40 caractères maximum.",
  "El nombre puede tener hasta 64 caracteres y la contraseña hasta 128.": "Le nom peut contenir 64 caractères maximum et le mot de passe 128.",
  "El nombre tiene que tener entre 2 y 90 caracteres.": "Le nom doit faire entre 2 et 90 caractères.",
  "El nombre y la web salen en tu ficha; el CIF no se publica.": "Le nom et le site apparaissent sur ta fiche ; le CIF n’est pas publié.",
  "El pago con tarjeta aún no está disponible. Escríbenos a info@klendar.app.": "Le paiement par carte n’est pas encore disponible. Écris-nous à info@klendar.app.",
  "El pago lo hace Stripe: Klendar no ve ni guarda tu tarjeta ni tu cuenta. Te pedirá el nombre fiscal, el NIF y la dirección para la factura. Un cobro por domiciliación tarda unos días en confirmarse; mientras, tu negocio funciona con normalidad.": "Le paiement est géré par Stripe : Klendar ne voit ni ne conserve ta carte ni ton compte. Il te demandera la raison sociale, le numéro fiscal et l'adresse pour la facture. Un prélèvement met quelques jours à être confirmé ; en attendant, ton commerce fonctionne normalement.",
  "El pago lo hace Stripe: Klendar no ve ni guarda tu tarjeta. Te pedirá el nombre fiscal, el NIF y la dirección para la factura.": "Le paiement est géré par Stripe : Klendar ne voit ni ne conserve ta carte. Il te demandera la raison sociale, le numéro fiscal et l’adresse pour la facture.",
  "El periodo en cuatro cifras": "La période en quatre chiffres",
  "El plan lo gestiona el propietario del negocio.": "La formule est gérée par le propriétaire du commerce.",
  "El plan no está en pausa.": "La formule n’est pas en pause.",
  "El plan ya está en pausa.": "La formule est déjà en pause.",
  "El plazo para aceptar el premio va de 3 a 30 días.": "Le délai pour accepter le lot va de 3 à 30 jours.",
  "El precio anterior tiene que ser mayor que el de ahora.": "Le prix précédent doit être supérieur au prix actuel.",
  "El premio es otro código que validas igual, o lo entregas tú desde la lista de clientes de la tarjeta, donde también puedes añadir o quitar sellos y ponerla a 0. Si apagas una tarjeta,": "La récompense est un autre code que tu valides de la même façon, ou que tu remets toi-même depuis la liste des clients de la carte, où tu peux aussi ajouter ou retirer des tampons et la remettre à 0. Si tu désactives une carte,",
  "El primer local paga la cuota entera; los siguientes, menos.": "Le premier lieu paie l’abonnement complet ; les suivants, moins.",
  "El propietario no sale del equipo: traspasa el negocio o dalo de baja.": "Le propriétaire ne peut pas quitter l’équipe : transfère le commerce ou retire-le.",
  "El QR no lleva la contraseña: si la cambias, los carteles siguen valiendo. Contamos escaneos, no personas: no guardamos quién escanea.": "Le QR ne contient pas le mot de passe : si tu le changes, les chevalets restent valables. Nous comptons les scans, pas les personnes : nous ne gardons pas qui scanne.",
  "El que sale en la tele al abrir klendar.app/tv. Cambia cada 10 minutos.": "Celui qui s’affiche à la télé quand tu ouvres klendar.app/tv. Il change toutes les 10 minutes.",
