  "Escanea el QR con la cámara (la del móvil o la del portátil) o escribe el código que la persona tiene debajo del QR. Cada código vale una vez: al validarlo queda marcado y el aforo baja.": "Scanne le QR code avec la caméra (celle du téléphone ou de l’ordinateur) ou saisis le code que la personne a sous son QR code. Chaque code ne sert qu’une fois : une fois validé, il est marqué et la capacité diminue.",
