  "Escrita, además, se puede buscar y la lee un lector de pantalla; si la escribes, es lo primero que se ve y los archivos y el enlace se quedan debajo. Si no te apetece, con una foto o un PDF vas servido.": "Écrite, elle peut aussi être recherchée et lue par un lecteur d’écran ; si tu l’écris, c’est ce qui s’affiche en premier, et les fichiers et le lien restent en dessous. Si tu n’en as pas envie, une photo ou un PDF suffit.",
