  "Estamos mirando el documento; normalmente tardamos 24–48 h. Hasta que lo verifiquemos no se puede publicar, pero ya puedes completar la ficha.": "On examine le document ; cela prend en général 24 à 48 h. Tant qu’il n’est pas vérifié, impossible de publier, mais tu peux déjà compléter ta fiche.",
  "Estamos revisando tu negocio; normalmente tardamos 24–48 h. Mientras tanto puedes preparar la ficha y tus publicaciones: se harán públicas al verificarlo. Si pasan más de 48 h sin noticias, escríbenos.": "Nous vérifions ton commerce ; cela prend généralement 24 à 48 h. En attendant, tu peux préparer ta fiche et tes publications : elles seront visibles une fois le commerce vérifié. Si tu n’as pas de nouvelles après 48 h, écris-nous.",
