  "Este panel hace lo mismo que la app, desde el ordenador o desde el navegador del móvil: dar de alta el negocio, publicar ofertas y eventos, ver cómo van, validar códigos en la puerta y llevar el equipo.": "Ce tableau de bord fait la même chose que l’app, depuis un ordinateur ou le navigateur du téléphone : inscrire le commerce, publier des offres et des événements, suivre leurs résultats, valider les codes à l’entrée et gérer l’équipe.",
