  "Has vuelto a abrir": "Tu as rouvert",
  "Hasta": "À",
  "Hasta 12 fotos: el local, el ambiente, lo que haces. Se ven en tu ficha.": "Jusqu’à 12 photos : l’établissement, l’ambiance, ce que tu fais. Elles apparaissent sur ta fiche.",
  "Hasta 6 fotos o vídeos. La primera es la portada; muévelas con las flechas. Si no pones ninguna, se usa la foto del local. Los vídeos se ven al abrir la publicación (en el feed van las fotos).": "Jusqu’à 6 photos ou vidéos. La première est la couverture ; déplace-les avec les flèches. Si tu n’en mets aucune, la photo de l’établissement est utilisée. Les vidéos se voient en ouvrant la publication (le fil affiche les photos).",
  "Hasta cuándo": "Jusqu'à quand",
  "Hasta cuántas personas": "Jusqu’à combien de personnes",
  "Hasta entonces sigue en prueba. Ese día se suma a la suscripción que ya pagas ({de}) y Stripe ajusta la próxima factura.": "D’ici là, il reste en essai. Ce jour-là, il rejoint l’abonnement que tu paies déjà ({de}) et Stripe ajuste la prochaine facture.",
  "Hasta entonces sigue en prueba. Ese día se suma a la suscripción que ya pagas y Stripe ajusta la próxima factura.": "D’ici là, il reste en essai. Ce jour-là, il rejoint l’abonnement que tu paies déjà et Stripe ajuste la prochaine facture.",
  "Hasta las {hora}": "Jusqu’à {hora}",
  "Hasta que aceptes una propuesta, los negocios no ven quién eres.": "Tant que tu n’as pas accepté une proposition, les établissements ne savent pas qui tu es.",
