  "Hay 1 reserva o código sin usar: sigue valiendo. Si no vas a atenderlo, cancela esa publicación.": "Il reste 1 réservation ou code non utilisé : il reste valable. Si tu ne comptes pas l’honorer, annule cette publication.",
  "Hay alguien en el equipo menor de 18 años (o sin fecha de nacimiento en su perfil). Quítalo del equipo antes de marcar el negocio como +18.": "Quelqu’un dans l’équipe a moins de 18 ans (ou n’a pas de date de naissance dans son profil). Retire cette personne de l’équipe avant de marquer l’établissement comme +18.",
  "Hay cambios en esta publicación que todavía no has guardado.": "Certaines modifications de cette publication ne sont pas encore enregistrées.",
