  "Hay gente con reserva": "Des personnes ont réservé",
  "Hay palabras que no podemos aceptar. Revisa lo que has escrito.": "Certains mots ne sont pas acceptés. Vérifie ce que tu as écrit.",
  "Hay que responder: varias comunidades prohíben el 2x1 en bebidas alcohólicas y la sanción es para el negocio. Si el 2x1 es de comida, refrescos o servicios, marca «No lleva alcohol».": "Réponse obligatoire : plusieurs régions interdisent le 2 pour 1 sur les boissons alcoolisées et c’est le commerce qui est sanctionné. Si le 2 pour 1 porte sur de la nourriture, des sodas ou des prestations, choisis « Sans alcool ».",
  "Hay sitio": "Il y a de la place",
  "Hay un pago pendiente del plan.": "Un paiement de la formule est en attente.",
  "Hay un pago pendiente desde el {hold_since}. Tus publicaciones no se ven hasta que se resuelva; no se ha borrado nada.": "Un paiement est en attente depuis le {hold_since}. Tes publications sont masquées jusqu’à ce que ce soit réglé ; rien n’a été supprimé.",
  "Hay un texto demasiado largo.": "Un des textes est trop long.",
  "Hay {codes} código sin usar de {antes}. Si lo dejas en {ahora}, esas personas pagarán {ahora} en el local. A quien ya canjeó no se le avisa.": "Il y a {codes} code non utilisé à {antes}. Si tu le passes à {ahora}, ces personnes paieront {ahora} sur place. Ceux qui ont déjà utilisé l’offre ne sont pas prévenus.",
  "Hay {codes} códigos sin usar de {antes}. Si lo dejas en {ahora}, esas personas pagarán {ahora} en el local. A quien ya canjeó no se le avisa.": "Il y a {codes} codes non utilisés à {antes}. Si tu le passes à {ahora}, ces personnes paieront {ahora} sur place. Ceux qui ont déjà utilisé l’offre ne sont pas prévenus.",
  "Hay {n} cambios más en el historial.": "Il y a {n} autres modifications dans l’historique.",
  "Hay {vivas} reservas o códigos sin usar: siguen valiendo. Si no vas a atenderlos, cancela esas publicaciones.": "Il reste {vivas} réservations ou codes non utilisés : ils restent valables. Si tu ne comptes pas les honorer, annule ces publications.",
  "Hazlo al cerrar. Al empezar otro día vuelve a 0 solo.": "Fais-le à la fermeture. Au début d’une nouvelle journée, ça revient à 0 tout seul.",
  "Hazlo solo si no puede enseñar su QR de cliente. Le llegará un aviso con los usos que le quedan.": "Fais-le seulement si la personne ne peut pas montrer son QR client. Elle recevra une notification avec les utilisations restantes.",
