  "Marca las que ya no uses. Las publicaciones hechas con ellas no cambian.": "Coche ceux que tu n’utilises plus. Les publications créées avec eux ne changent pas.",
  "Marca lo que pongas y saldrá en tu ficha y en «Dónde ver el partido».": "Coche ce que tu diffuses et ça apparaîtra sur ta fiche et dans « Où voir le match ».",
  "Marca lo que tenga tu local: sale en tu ficha y la gente lo puede buscar en los filtros.": "Coche ce que propose ton établissement : ça apparaît sur ta fiche et les gens peuvent le chercher dans les filtres.",
  "Marca «Aceptamos grupos» y saldrás en «Grupos y empresas»: la gente elige hasta 3 negocios y les pide presupuesto a la vez (fecha, personas, presupuesto por persona y una nota).": "Coche « On accueille les groupes » et tu apparaîtras dans « Groupes et entreprises » : les gens choisissent jusqu’à 3 établissements et leur demandent un devis en même temps (date, nombre de personnes, budget par personne et une note).",
