  "No hemos podido cargar tu ficha.": "Impossible de charger ta fiche.",
  "No hemos podido cobrar. Si no se resuelve antes del {bloqueoEl}, tu negocio quedará bloqueado (no se borra nada).": "Nous n'avons pas pu encaisser le paiement. Si ce n'est pas réglé avant le {bloqueoEl}, ton commerce sera bloqué (rien n'est supprimé).",
  "No hemos podido cobrar. Si no se resuelve antes del {grace_until}, pausaremos tus publicaciones (no se borra nada).": "Le paiement n’a pas pu être encaissé. Si ce n’est pas réglé avant le {grace_until}, nous mettrons tes publications en pause (rien n’est supprimé).",
