  "No hemos podido saber dónde estás. Revisa el permiso de ubicación del navegador.": "Impossible de savoir où tu es. Vérifie l’autorisation de localisation du navigateur.",
  "No hemos podido terminar de entrar. Vuelve a intentarlo desde este navegador.": "Impossible de terminer la connexion. Réessaie depuis ce navigateur.",
  "No hemos podido verificar el negocio. Escríbenos a info@klendar.app.": "Nous n’avons pas pu vérifier le commerce. Écris-nous à info@klendar.app.",
