  "opcional": "facultatif",
  "Opcional. Si no lo pones, la cocina va con el horario del local. Se usa en la ficha, en «Se puede comer ahora» y en el Menú del día.": "Facultatif. Sinon, la cuisine suit les horaires de l’établissement. Utilisé sur ta fiche, dans « On peut manger maintenant » et dans le menu du jour.",
  "Opcional: lo puedes completar después desde Tu ficha.": "Facultatif : tu peux le compléter plus tard depuis Ta fiche.",
