  "Pega esta línea donde quieras que salga lo que tienes publicado. Se actualiza solo: no tienes que tocar nada más.": "Colle cette ligne là où tu veux afficher ce que tu as publié. Elle se met à jour toute seule : tu n’as rien d’autre à faire.",
  "Pega esta línea en tu web y saldrá lo que tienes publicado. Se actualiza sola.": "Colle cette ligne sur ton site et ce que tu as publié s’y affichera. Ça se met à jour tout seul.",
