  "Petición enviada. Te avisamos cuando contesten (tienen 72 horas).": "Demande envoyée. On te prévient quand ils répondent (ils ont 72 heures).",
  "Petición retirada": "Demande retirée",
  "Pide a la persona su código (lo tiene en la app, debajo del QR) y escríbelo aquí. Cada código vale una vez: al validarlo queda marcado y el aforo baja. Si tienes cámara, desde la app es más rápido.": "Demande à la personne son code (il est dans l’app, sous le QR code) et saisis-le ici. Chaque code ne sert qu’une fois : une fois validé, il est marqué et la capacité diminue. Si tu as une caméra, c’est plus rapide depuis l’app.",
