  "Plan en pausa hasta el {paused_until}: no se cobra y tus publicaciones no se ven. Todo lo demás se queda como está.": "Formule en pause jusqu’au {paused_until} : rien n’est facturé et tes publications sont masquées. Tout le reste reste tel quel.",
