  "Planes en los que se está a gusto sin compañía o se conoce gente: una cata en barra, un taller, un club de lectura.": "Des plans où l’on se sent bien sans compagnie ou où l’on rencontre du monde : une dégustation au comptoir, un atelier, un club de lecture.",
  "Planes para todas las edades que marques.": "Des plans pour tous les âges cochés.",
