  "Podrás publicar cuando verifiquemos la entidad.": "Tu pourras publier une fois l’organisation vérifiée.",
  "Pon al menos el título antes de guardarla.": "Indique au moins le titre avant de l’enregistrer.",
  "Pon el código «sin caducidad» para que valga como entrada.": "Règle le code sur « Sans expiration » pour qu’il serve d’entrée.",
  "Pon el nombre del negocio (dos letras como mínimo).": "Indique le nom du commerce (deux caractères minimum).",
  "Pon el nombre del negocio.": "Indique le nom de l’établissement.",
  "Pon el precio anterior: la ley obliga a enseñarlo junto al descuento.": "Indique le prix précédent : la loi oblige à l’afficher à côté de la réduction.",
  "Pon el precio del menú (entre 1 y 200 €).": "Indique le prix du menu (entre 1 et 200 €).",
