  "Ponle un nombre de 2 a 30 caracteres.": "Donne-lui un nom de 2 à 30 caractères.",
  "Ponlo en el mostrador. Quien pide lo escanea y le avisamos cuando su pedido esté listo. Vale todos los días.": "Mets-la sur le comptoir. Les clients la scannent et on les prévient quand leur commande est prête. Elle sert tous les jours.",
  "por": "par",
  "Por ahora los sorteos no están disponibles en Klendar. Lo demás de Fidelizar funciona como siempre.": "Les tirages au sort ne sont pas disponibles sur Klendar pour l'instant. Le reste de Fidéliser fonctionne comme d'habitude.",
  "Por ahora no hay sorteos en Klendar. Mientras, mira lo que hay hoy cerca de ti.": "Il n'y a pas de tirages au sort sur Klendar pour l'instant. En attendant, découvre ce qui se passe près de toi aujourd'hui.",
  "Por ahora no tiene fechas": "Pas de date pour l’instant",
  "por alguien del equipo": "par un membre de l’équipe",
  "Por cada código validado sumamos el precio de la oferta por persona (el que tenía cuando la persona consiguió el código) por las plazas.": "Pour chaque code validé, on additionne le prix de l’offre par personne (celui qu’elle avait quand la personne a obtenu le code) multiplié par le nombre de places.",
  "Por contestar": "À répondre",
