  "Quien escanee el cartel del local en tu negocio se lleva un sello, como mucho uno al día.": "Toute personne qui scanne l’affiche dans ton établissement gagne un tampon, au maximum un par jour.",
  "Quien la sigue recibirá un aviso cuando se publique.": "Ceux qui la suivent recevront une notification à la publication.",
  "Quien llega escanea el cartel de la puerta, coge número y le avisamos en el móvil cuando le toca. Tú solo tocas «Avisar al siguiente».": "Les gens qui arrivent scannent l’affiche à l’entrée, prennent un numéro et on les prévient sur leur téléphone quand c’est leur tour. Toi, tu appuies juste sur « Appeler le suivant ».",
  "Quien llega lo escanea con el móvil y coge número. Imprímelo y ponlo en la puerta.": "En arrivant, on le scanne avec son téléphone et on prend un numéro. Imprime-le et affiche-le à l’entrée.",
  "Quien pide en el mostrador escanea el cartel y le avisamos en el móvil cuando su pedido está listo. Tú solo tocas «Listo».": "Les clients qui commandent au comptoir scannent l’affiche et on les prévient sur leur téléphone quand c’est prêt. Toi, tu touches juste « Prêt ».",
  "Quien siga la serie recibirá un aviso con cada fecha nueva.": "Ceux qui suivent la série recevront une notification à chaque nouvelle date.",
  "Quien te tenga en favoritos recibe una notificación (como mucho una al día por negocio, para no cansar).": "Ceux qui t’ont en favori reçoivent une notification (une par jour maximum par commerce, pour ne pas lasser).",
