  "Sigue a tu equipo y te avisamos antes de cada partido con los bares que lo ponen cerca.": "Suis ton équipe et on te prévient avant chaque match avec les bars qui le diffusent près de toi.",
  "Sigue a tus artistas y te avisamos cuando tengan una fecha nueva cerca de ti.": "Suis tes artistes et on te prévient quand ils ont une nouvelle date près de toi.",
  "Sigue al equipo y te avisamos antes del partido si algún bar cercano lo pone.": "Suis l’équipe et on te prévient avant le match si un bar proche le diffuse.",
