  "Sobria: panel liso y el color solo en el precio.": "Sobre : panneau uni et la couleur seulement sur le prix.",
  "Soja": "Soja",
  "Solicitud enviada el {fecha}. Te avisamos cuando la revisemos.": "Demande envoyée le {fecha}. On te prévient dès qu’elle est examinée.",
  "Solicitud enviada. Ahora completa la ficha: logo, portada y horarios.": "Demande envoyée. Maintenant, complète ta fiche : logo, couverture et horaires.",
  "Solicitud enviada. Te avisamos cuando la revisemos.": "Demande envoyée. On te prévient dès qu’elle est examinée.",
