  "Solo cuenta como asistencia lo validado en la puerta. Lo que pagues a tus RRPP lo gestionas fuera de Klendar; tú eres responsable de tus RRPP.": "Seules les entrées validées à la porte comptent comme présence. Ce que tu paies à tes promoteurs se gère en dehors de Klendar ; tu es responsable de tes promoteurs.",
