  "Solo el propietario del negocio puede pagar el plan.": "Seul le propriétaire du commerce peut payer la formule.",
  "Solo el propietario o un encargado puede cambiarlo.": "Seul le propriétaire ou un responsable peut le modifier.",
  "Solo el propietario o un encargado pueden cambiarlo.": "Seuls le propriétaire ou un responsable peuvent le modifier.",
  "Solo el propietario o un encargado pueden enlazar teles.": "Seuls le propriétaire ou un responsable peuvent associer des télés.",
  "Solo el propietario o un encargado pueden enviar mensajes.": "Seuls le propriétaire ou un responsable peuvent envoyer des messages.",
  "Solo el propietario puede abrirlo de nuevo.": "Seul le propriétaire peut le rouvrir.",
  "Solo el propietario puede dar de baja el negocio.": "Seul le propriétaire peut retirer le commerce.",
  "Solo el propietario puede volver a abrirlo.": "Seul le propriétaire peut le rouvrir.",
  "Solo el propietario y los encargados pueden crear o editar publicaciones.": "Seuls le propriétaire et les responsables peuvent créer ou modifier des publications.",
  "Solo enlaces de Spotify, YouTube, SoundCloud, Apple Music o Bandcamp.": "Uniquement des liens Spotify, YouTube, SoundCloud, Apple Music ou Bandcamp.",
  "Solo eventos": "Événements uniquement",
  "Solo favoritos": "Favoris uniquement",
  "Solo fotos (JPG, PNG, WebP o HEIC) y PDF.": "Seulement des photos (JPG, PNG, WebP ou HEIC) et des PDF.",
  "Solo la podrá sacar quien no haya canjeado nunca nada en tu negocio. Tu equipo no cuenta.": "Seuls ceux qui n’ont jamais rien utilisé dans ton établissement pourront l’obtenir. Ton équipe ne compte pas.",
  "Solo la ve quien entra por el enlace o el QR de un RRPP.": "Seuls ceux qui passent par le lien ou le QR d’un promoteur la voient.",
  "Solo la ven ellos. Si a otra persona le llega el enlace, la ficha dice que es exclusiva y cómo conseguirla, sin enseñar el beneficio.": "Eux seuls la voient. Si quelqu’un d’autre reçoit le lien, la fiche indique que c’est une exclusivité et comment l’obtenir, sans montrer l’avantage.",
  "Solo la verán mayores de 18. Comprueba que tu comunidad lo permite.": "Seuls les plus de 18 ans la verront. Vérifie que ta région l’autorise.",
  "Solo lo que publican ayuntamientos, juntas de distrito, asociaciones y ONG, y la agenda municipal.": "Seulement ce que publient les mairies, mairies d’arrondissement, associations et ONG, et l’agenda municipal.",
  "Solo lo verá {x}. A los demás les diremos que has elegido otra.": "Seul {x} le verra. On dira aux autres que tu en as choisi une autre.",
  "Solo mayores de 18": "Réservé aux plus de 18 ans",
  "Solo ofertas flash": "Offres flash uniquement",
  "Solo para mayores de 18": "Réservé aux plus de 18 ans",
  "Solo para mayores de 18 (todo lo que publiques quedará marcado y todo el equipo tiene que ser mayor de edad)": "Réservé aux plus de 18 ans (tout ce que tu publies sera marqué et toute l’équipe doit être majeure)",
  "Solo para mayores de 18 (todo lo que publiques quedará marcado)": "Réservé aux plus de 18 ans (tout ce que tu publies sera marqué)",
  "Solo para quien lo enseñe. Klendar no lo comprueba: lo mira tu equipo en la puerta (el escáner se lo recuerda).": "Seulement pour ceux qui la présentent. Klendar ne la vérifie pas : c’est ton équipe qui la regarde à l’entrée (le scanner le lui rappelle).",
  "Solo para quien reserva. Su QR cambia cada 30 segundos (una captura no sirve) y en la puerta ves su nombre, su foto si la tiene y cuántas veces ha venido.": "Uniquement pour la personne qui réserve. Son QR change toutes les 30 secondes (une capture ne sert à rien) et à l’entrée tu vois son nom, sa photo si elle en a une et combien de fois elle est venue.",
  "Solo para quien viene por primera vez": "Seulement pour une première visite",
  "Solo puedes incluir locales de los que eres propietario.": "Tu ne peux inclure que des lieux dont tu es propriétaire.",
  "Solo quien tiene tu negocio en favoritos": "Seulement ceux qui ont ton commerce en favori",
  "Solo RRPP": "Promoteurs uniquement",
  "Solo se pueden poner sellos a quien ya ha canjeado algo en tu negocio.": "Tu ne peux donner des tampons qu’aux personnes qui ont déjà utilisé une offre dans ton commerce.",
  "Solo si eliges «Una serie nueva».": "Seulement si tu choisis « Une nouvelle série ».",
  "Solo si es distinto de tu local.": "Seulement si c’est différent de ton établissement.",
  "Solo si este plan es distinto de tu local (p. ej. un taller infantil o un concierto en el patio).": "Seulement si ce plan diffère de ton établissement (ex. un atelier pour enfants ou un concert dans la cour).",
  "Solo tú": "Juste toi",
  "Solo ves su nombre visible y cuántas veces han venido: nada de datos de contacto. El regalo les llega como un código.": "Tu vois seulement leur nom affiché et combien de fois ils sont venus : aucune coordonnée. Le cadeau leur arrive sous forme de code.",
  "Somos una entidad": "Nous sommes une entité",
  "Son 6 cifras.": "Il faut 6 chiffres.",
  "son los catorce que obliga a declarar el Reglamento 1169/2011. Pon solo los que sepas seguro: aquí equivocarse no es una errata.": "sont les quatorze que le règlement (UE) 1169/2011 oblige à déclarer. N’indique que ceux dont tu es sûr : ici, une erreur n’est pas une simple coquille.",
  "Sonido": "Son",
  "Sorteas algo tuyo (una manicura, una cena para dos…) entre quien participe en la app o en klendar.app.": "Tu fais gagner quelque chose de chez toi (une manucure, un dîner pour deux…) parmi ceux qui participent dans l’app ou sur klendar.app.",
