  "sí": "oui",
  "Sí puedes validar los códigos y bonos que ya tiene la gente: lo que ya diste se respeta (bonos vendidos, sellos, premios, códigos y sorteos abiertos).": "Tu peux quand même valider les codes et les carnets que les gens ont déjà : ce que tu as déjà donné est respecté (carnets vendus, tampons, récompenses, codes et tirages au sort ouverts).",
  "Sí, abro hoy": "Oui, j’ouvre aujourd’hui",
  "Sí, lleva alcohol": "Oui, avec alcool",
  "Súmalo a la suscripción que ya pagas ({de}), con los mismos datos de factura: el precio por local baja con la escalera y Stripe ajusta la próxima factura.": "Ajoute-le à l’abonnement que tu paies déjà ({de}), avec les mêmes informations de facturation : le prix par établissement baisse avec le barème et Stripe ajuste la prochaine facture.",
  "Súmalo a la suscripción que ya pagas, con los mismos datos de factura: el precio por local baja con la escalera y Stripe ajusta la próxima factura.": "Ajoute-le à l’abonnement que tu paies déjà, avec les mêmes informations de facturation : le prix par établissement baisse avec le barème et Stripe ajuste la prochaine facture.",
  "Taller de pan de masa madre": "Atelier pain au levain",
  "Taller infantil gratis": "Atelier enfants gratuit",
  "Tamaño mesa: cuatro por folio, para recortar y poner en las mesas.": "Format table : quatre par feuille, à découper et à poser sur les tables.",
  "También por visita con el QR del local": "Aussi par visite avec le QR code de l’établissement",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva, y la persona que la sigue recibirá un aviso.": "Les prochaines dates sont aussi annulées, avec une alerte à qui a une réservation, et la personne qui la suit recevra une alerte.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva, y las {n} personas que la siguen recibirán un aviso.": "Les prochaines dates sont aussi annulées, avec une alerte à qui a une réservation, et les {n} personnes qui la suivent recevront une alerte.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva.": "Les prochaines dates sont aussi annulées, avec une alerte à qui a une réservation.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva{n}.": "Les prochaines dates sont aussi annulées, et ceux qui ont réservé sont prévenus{n}.",
