  "Vacaciones": "Vacances",
  "Vacaciones, festivos, obras. Esos días no se ve nada de tu negocio, como con «Cerrado por hoy», y tu ficha dice hasta cuándo cierras. Al acabar, todo vuelve a verse solo.": "Vacances, jours fériés, travaux. Ces jours-là, rien de ton commerce n’apparaît, comme avec « Fermé aujourd’hui », et ta fiche indique jusqu’à quand tu fermes. Ensuite, tout réapparaît automatiquement.",
  "Vacaciones, obras, un festivo… Esos días no se ve nada de tu negocio.": "Vacances, travaux, un jour férié… Ces jours-là, rien de ton établissement ne s’affiche.",
