  "Vale desde el día siguiente al canje y se valida en «Validar códigos», como los demás. Uno por canje; tu equipo no los recibe. Si menciona alcohol, solo lo reciben mayores de edad.": "Valable à partir du lendemain de l’utilisation et validé dans « Valider les codes », comme les autres. Un par utilisation ; ton équipe n’en reçoit pas. S’il mentionne de l’alcool, seuls les majeurs le reçoivent.",
