  "Ya has vendido {sold}. Lo que cambies vale para los próximos: los vendidos siguen como se vendieron.": "Tu en as déjà vendu {sold}. Tes modifications valent pour les prochains : ceux déjà vendus restent tels qu’ils ont été vendus.",
