  "Ya no aparece en Klendar y sus publicaciones se han cancelado. Si es un error o vuelve a abrir, escríbenos.": "Il n’apparaît plus sur Klendar et ses publications ont été annulées. Si c’est une erreur ou s’il rouvre, écris-nous.",
