  "Ya no está al día": "Elle n’est plus à jour",
  "Ya no está en la cola.": "Cette personne n’est plus dans la file.",
  "Ya no está: puede que haya caducado.": "Ce n’est plus là : ça a peut-être expiré.",
  "Ya no lo espera": "N’attend plus",
  "ya no podrá aceptarla.": "ne pourra plus l’accepter.",
  "Ya no se puede deshacer: han pasado más de 10 minutos.": "Impossible d’annuler : plus de 10 minutes se sont écoulées.",
  "Ya no se sumará": "Il ne rejoindra plus l’abonnement",
  "Ya no sigues a {n}": "Tu ne suis plus {n}",
  "Ya no sigues a {n}.": "Tu ne suis plus {n}.",
  "Ya no tiene página en Klendar": "N’a plus de page sur Klendar",
