  "«{title}» se publicará sola los días y la hora que elijas, con su cuenta atrás y su aforo. Puedes pausarla cuando quieras.": "« {title} » sera publié tout seul les jours et à l’heure que tu choisis, avec son compte à rebours et sa capacité. Tu peux le mettre en pause quand tu veux.",
